/* 바다 정보(수온·파고·바람)를 받아서 작은 파일 하나로 만든다.
 *
 * 🔴 왜 여기서 받나 — 앱이 직접 부르면 두 가지가 막힌다.
 *   ① **인증키가 공개된다.** 우리 앱은 서버가 없어 코드가 통째로 폰에 내려간다.
 *   ② **브라우저가 공공데이터포털을 직접 못 부른다**(CORS).
 * 그래서 깃허브가 대신 받아서 파일로 만들어 둔다. 키는 깃허브 비밀값에만 있다.
 *
 * 🔴 이 파일은 `data` 가지에만 올린다. `main` 에 올리면 앱이 통째로 다시 배포되고
 *    판 번호가 바뀌어 **사용자들이 4MB를 다시 받는다.** 15분마다 그러면 안 된다.
 */
import fs from 'node:fs';

/* 🔴 2026-08-13 (고침) — 한 곳만 보면 안 된다.
 *
 * 처음에는 해역마다 관측소를 **하나씩만** 정해뒀는데, 첫 실행에서 드러났다 —
 *   · 인천항·여수항 부이는 값을 **아예 안 줬다**
 *   · 속초·중문 해수욕장 부이는 **어젯밤 값**이었다(13시간 전)
 *   · 그래서 **파고가 어디에도 안 떴고, 동해는 카드가 통째로 안 떴다**
 *
 * 🟢 그래서 해역마다 **여러 곳을 물어보고 가장 최근 것**을 쓴다.
 *    한 곳이 쉬어도 다른 곳이 받쳐준다. 값이 없으면 그 칸을 안 만드는 원칙은 그대로다.
 *
 * 🔴 2026-08-13 (다시 고침) — **다섯~여섯 곳은 너무 많았다. 셋으로 줄인다.**
 *    한 번 돌 때 최대 4바다 × (수온 3 + 부이 3) = **24번**을 부른다.
 *    30분마다면 하루 48회 × 24 = **1,152번**이다. 공공데이터포털에는 하루 한도가 있고
 *    15분마다 × 서른여덟 곳이면 하루 삼천 번이 넘어 한도를 넘길 수 있었다. [Unverified — 정확한 한도는 마이페이지에서 확인해야 한다]
 *    🟢 어차피 **최근 것을 찾으면 거기서 멈추므로** 평소에는 바다마다 한두 번만 부른다. */
const 관측소 = {
  서해: {
    수온: [['DT_0001', '인천'], ['DT_0043', '영흥도'], ['DT_0018', '군산']],
    부이: [['TW_0076', '인천항'], ['TW_0069', '대천해수욕장'], ['TW_0079', '상왕등도']],
  },
  동해: {
    수온: [['DT_0012', '속초'], ['DT_0006', '묵호'], ['DT_0011', '후포']],
    부이: [['TW_0093', '속초해수욕장'], ['TW_0094', '망상해수욕장'], ['KG_0101', '울릉도북동']],
  },
  남해: {
    수온: [['DT_0016', '여수'], ['DT_0014', '통영'], ['DT_0005', '부산']],
    부이: [['TW_0083', '여수항'], ['TW_0084', '통영항'], ['KG_0025', '남해동부']],
  },
  제주: {
    수온: [['DT_0004', '제주'], ['DT_0010', '서귀포'], ['DT_0022', '성산포']],
    부이: [['TW_0075', '중문해수욕장'], ['KG_0021', '제주남부'], ['KG_0028', '제주해협']],
  },
};
/* 관측일시를 견줄 수 있는 숫자로 — 못 읽으면 0(가장 오래된 것으로 친다) */
function 언제(글) {
  if (!글) return 0;
  const t = new Date(String(글).replace(' ', 'T') + (String(글).length <= 16 ? ':00' : ''));
  return isNaN(t) ? 0 : t.getTime();
}

const 키 = process.env.DATA_GO_KR_KEY || '';
if (!키) { console.log('[바다] 인증키가 없습니다 — 건너뜁니다.'); process.exit(0); }

const 밑 = 'https://apis.data.go.kr/1192136';
const 공통 = `serviceKey=${encodeURIComponent(키)}&type=json&min=60&pageNo=1&numOfRows=24`;

/* 🔴 2026-08-13 (고침) — 실패 이유를 **삼키지 않는다.**
 *
 * 처음에는 실패하면 조용히 null 을 돌려줬는데, 그 바람에 자료가 통째로 비었을 때
 * **왜 비었는지 알 수가 없었다.** 오늘 자에서 배운 것과 같다 — 추측하지 말고 재야 한다.
 * 이제 상태와 답의 앞부분을 로그에 찍는다. 실패해도 나머지는 계속 돈다. */
async function 불러오기(주소, 이름) {
  try {
    const r = await fetch(주소);
    const 글 = await r.text();
    if (!r.ok) {
      console.log(`  [실패] ${이름} — HTTP ${r.status} ${글.slice(0, 160).replace(/\s+/g, ' ')}`);
      return null;
    }
    try {
      return JSON.parse(글);
    } catch (e) {
      /* 🔴 공공데이터포털은 오류일 때 json 을 달라 해도 xml 로 답한다.
         그래서 「글자를 못 읽었다」가 아니라 **무슨 오류인지**를 찍어야 한다 */
      console.log(`  [오류] ${이름} — ${글.slice(0, 220).replace(/\s+/g, ' ')}`);
      return null;
    }
  } catch (e) {
    console.log(`  [못감] ${이름} — ${e.message}`);
    return null;
  }
}

/* 잠깐 쉬기 — 한꺼번에 스무 개를 던지면 막힐 수 있다 */
const 쉬기 = (ms) => new Promise((r) => setTimeout(r, ms));

/* 마지막 한 줄 = 가장 최근 관측값 */
function 마지막(답) {
  const 목록 = 답 && 답.body && 답.body.items && 답.body.items.item;
  if (!목록) return null;
  const 줄들 = Array.isArray(목록) ? 목록 : [목록];
  return 줄들.length ? 줄들[줄들.length - 1] : null;
}

const 결과 = { 만든때: new Date().toISOString(), 바다: {} };

/* ────────────────────────────
 * 🔴 2026-08-14 — **왜 안 뜨는지를 파일에 같이 적는다** (사장님 지시)
 *
 * 오늘 아침 자료를 보니 **파고가 동해·제주에만 있고 서해·남해가 비어 있었다.**
 * 🔴 그런데 **왜 비었는지 알 방법이 없었다** — 까닭은 깃허브 로그에만 찍히고,
 * 로그는 며칠 뒤에 지워지며, 그걸 보려면 사람이 웹에 들어가 클릭해야 한다.
 *
 * 🔵 **하필 서해·남해가 우리 사용자가 실제로 가는 바다다**(`PRD §2` — 수도권 거주 +
 * 주말 서해·남해 원정). 가장 필요한 곳이 비어 있는데 까닭을 모르는 상태였다.
 *
 * 🟢 **그래서 부이 코드를 더 넣어보는 대신, 먼저 재기로 했다.**
 * 코드를 짐작해 늘리면 그건 추측이고, 늘려도 왜 되는지 안 되는지 여전히 모른다.
 * 이제 관측소마다 **무슨 일이 있었는지 한 줄씩** `진단.json` 에 적는다 —
 * 「자료 0건」인지 「값은 왔는데 파고 칸이 없다」인지 「15시간 전 것」인지.
 *
 * 🔴 **진단은 따로 된 파일이다. `바다.json` 에 섞지 않는다.**
 * 바다.json 은 사용자 폰이 30분마다 받는 파일이라 한 글자도 무겁게 하면 안 된다.
 * ──────────────────────────── */

/* 관측소 하나가 어떤 상태인지 사람 말로 — 진단에 그대로 들어간다 */
function 상태말(줄) {
  if (!줄) return '자료 0건';
  const 때 = 언제(줄.obsrvnDt);
  if (!때) return `관측시각을 못 읽음(${줄.obsrvnDt || '빈칸'})`;
  const 시간 = Math.round((Date.now() - 때) / 36e5);
  const 있는것 = [];
  if (줄.wtem != null) 있는것.push('수온');
  if (줄.wvhgt != null) 있는것.push('파고');
  if (줄.wspd != null) 있는것.push('바람');
  return `${시간}시간 전 · ${있는것.length ? 있는것.join('·') : '값 칸이 다 비어 있음'}`;
}

/* 여러 곳을 한꺼번에 물어보고 **가장 최근 것** 하나를 고른다 */
/* 🔴 하나씩 차례로 부른다. 한꺼번에 던지면 막힌다.
 *    이미 최근 것(세 시간 안쪽)을 찾으면 **거기서 멈춘다** — 부르는 횟수를 아낀다 */
async function 가장최근(주소들) {
  const 모은것 = [];
  const 진단 = [];
  for (const [코드, 이름] of 주소들) {
    const 길 = 코드.startsWith('DT_')
      ? 'surveyWaterTemp/GetSurveyWaterTempApiService'
      : 'twRecent/GetTWRecentApiService';
    const 답 = await 불러오기(`${밑}/${길}?${공통}&obsCode=${코드}`, 이름);
    const 줄 = 마지막(답);
    진단.push(`${이름}(${코드}) — ${답 == null ? '부르기 실패' : 상태말(줄)}`);
    if (줄) {
      모은것.push({ 줄, 이름 });
      if (Date.now() - 언제(줄.obsrvnDt) < 3 * 3600 * 1000) break;
    }
    await 쉬기(250);
  }
  모은것.sort((a, b) => 언제(b.줄.obsrvnDt) - 언제(a.줄.obsrvnDt));
  /* 🔴 앞에서 멈췄으면 뒤엣것은 **안 물어본 것**이지 실패한 것이 아니다.
     그 차이를 안 적으면 진단을 잘못 읽는다 */
  const 안물어본수 = 주소들.length - 진단.length;
  if (안물어본수 > 0) 진단.push(`(뒤 ${안물어본수}곳은 안 물어봤다 — 앞에서 최근 것을 찾아서)`);
  return { 고른것: 모은것[0] || null, 진단 };
}

/* 🔴 진단은 따로 모은다 — 바다.json 에 안 섞는다 */
const 진단 = { 잰때: new Date().toISOString(), 바다: {} };

for (const [바다, 곳] of Object.entries(관측소)) {
  console.log(`[바다] ── ${바다} ──`);
  const { 고른것: 수온것, 진단: 수온진단 } = await 가장최근(곳.수온);
  const { 고른것: 부이것, 진단: 부이진단 } = await 가장최근(곳.부이);
  진단.바다[바다] = { 수온: 수온진단, 부이: 부이진단 };

  /* 🔴 값이 없으면 그 칸을 아예 안 만든다. 「-」나 0 을 지어내지 않는다 */
  const 한바다 = {};
  if (수온것 && 수온것.줄.wtem != null) {
    한바다.수온 = Number(수온것.줄.wtem);
    한바다.수온잰곳 = 수온것.이름;
    한바다.수온잰때 = 수온것.줄.obsrvnDt || '';
  }
  if (부이것) {
    const b = 부이것.줄;
    if (b.wvhgt != null) 한바다.파고 = Number(b.wvhgt);
    if (b.wspd != null) 한바다.풍속 = Number(b.wspd);
    /* 조위관측소가 쉬면 부이 수온으로 대신한다 — 더 최근일 때만 */
    if (b.wtem != null && (한바다.수온 == null || 언제(b.obsrvnDt) > 언제(한바다.수온잰때))) {
      한바다.수온 = Number(b.wtem);
      한바다.수온잰곳 = 부이것.이름;
      한바다.수온잰때 = b.obsrvnDt || '';
    }
    if (한바다.파고 != null || 한바다.풍속 != null) {
      한바다.바다잰곳 = 부이것.이름;
      한바다.바다잰때 = b.obsrvnDt || '';
    }
  }
  if (Object.keys(한바다).length) 결과.바다[바다] = 한바다;

  /* 🔴 **없는 칸을 한 줄로 적어둔다** — 이게 우리가 실제로 읽을 줄이다 */
  const 없는것 = [];
  if (한바다.수온 == null) 없는것.push('수온');
  if (한바다.파고 == null) 없는것.push('파고');
  if (한바다.풍속 == null) 없는것.push('바람');
  진단.바다[바다].없는것 = 없는것.length ? 없는것.join('·') : '없음 — 다 받았다';

  console.log(`[바다] ${바다}`, JSON.stringify(한바다));
  console.log(`[바다] ${바다} 못 받은 것: ${진단.바다[바다].없는것}`);
  for (const 줄 of [...수온진단, ...부이진단]) console.log(`         ${줄}`);
}

/* 🔴 진단 파일은 **자료를 하나도 못 받았을 때도** 만든다.
 *    그때가 바로 까닭이 가장 필요한 때다 */
fs.mkdirSync('바다자료', { recursive: true });
fs.writeFileSync('바다자료/진단.json', JSON.stringify(진단, null, 1), 'utf8');
console.log('[바다] 바다자료/진단.json 만들었습니다');

/* 🔴 2026-08-13 — **빈 자료로 덮어쓰지 않는다.**
 *
 * 이걸 안 해서 실제로 자료를 잃었다 — 2회차에 네 바다가 다 들어왔는데,
 * 3회차가 빈 채로 끝나면서 **그 좋은 자료를 `{}` 로 덮어썼다.**
 * 파일을 안 만들면 올리는 단계가 저절로 건너뛰고 **먼저 것이 그대로 남는다.**
 * 🔵 앱은 12시간 넘은 값을 안 보여주므로, 오래 실패하면 카드가 조용히 사라질 뿐 틀린 값을 보이지는 않는다. */
const 바다수 = Object.keys(결과.바다).length;
if (!바다수) {
  console.log('[바다] 🔴 한 바다도 못 받았습니다 — **파일을 만들지 않습니다.** 먼저 받아둔 자료를 그대로 둡니다.');
  console.log('[바다] 위의 [실패]·[오류]·[못감] 줄을 보세요. 거기에 이유가 적혀 있습니다.');
  process.exit(0);
}

fs.writeFileSync('바다자료/바다.json', JSON.stringify(결과), 'utf8');
console.log('[바다] 바다자료/바다.json 만들었습니다 —', 바다수, '개 바다');
